'use strict';
const products=[{id:'egg',name:'Single eggs',eggs:1},{id:'half',name:'Half crate',eggs:15},{id:'crate',name:'Full crate',eggs:30}];
const quantities=Object.fromEntries(products.map(p=>[p.id,0]));
const el=id=>document.getElementById(id);
const chosen=()=>products.filter(p=>quantities[p.id]>0);
function render(){el('summary').replaceChildren();const items=chosen();if(!items.length){el('summary').textContent='Choose a quantity to get started.';}else{for(const p of items){const row=document.createElement('div');row.textContent=quantities[p.id]+' × '+p.name;el('summary').append(row);}const note=document.createElement('strong');note.textContent='Price: confirmed on WhatsApp';el('summary').append(note);}el('checkout').disabled=!items.length;}
for(const p of products){const card=document.createElement('div');card.className='product';const icon=document.createElement('span');icon.className='icon';icon.textContent='🥚';icon.setAttribute('aria-hidden','true');const info=document.createElement('div');info.className='info';const title=document.createElement('h3');title.textContent=p.name;const detail=document.createElement('p');detail.textContent=p.eggs===1?'Choose the number of eggs':p.eggs+' eggs per '+(p.id==='half'?'half crate':'crate');info.append(title,detail);const controls=document.createElement('div');controls.className='counter';const minus=document.createElement('button');minus.type='button';minus.textContent='−';minus.setAttribute('aria-label','Remove '+p.name);const count=document.createElement('span');count.textContent='0';count.setAttribute('aria-live','polite');const plus=document.createElement('button');plus.type='button';plus.textContent='+';plus.setAttribute('aria-label','Add '+p.name);function change(delta){quantities[p.id]=Math.max(0,Math.min(999,quantities[p.id]+delta));count.textContent=quantities[p.id];minus.disabled=quantities[p.id]===0;plus.disabled=quantities[p.id]===999;render();}minus.onclick=()=>change(-1);plus.onclick=()=>change(1);minus.disabled=true;controls.append(minus,count,plus);card.append(icon,info,controls);el('products').append(card);}
el('method').onchange=()=>{const delivery=el('method').value==='delivery';el('addressWrap').hidden=!delivery;el('address').required=delivery;};
el('order').onsubmit=event=>{event.preventDefault();if(!chosen().length||!el('order').reportValidity())return;for(const id of ['name','phone',...(el('method').value==='delivery'?['address']:[])]){if(!el(id).value.trim()){el(id).setCustomValidity('Please complete this field.');el(id).reportValidity();el(id).oninput=()=>el(id).setCustomValidity('');return;}}const lines=['Hello Olaoyin Store, I would like to order:',...chosen().map(p=>quantities[p.id]+' × '+p.name),'Total eggs: '+chosen().reduce((n,p)=>n+p.eggs*quantities[p.id],0),'','Name: '+el('name').value.trim(),'Phone: '+el('phone').value.trim(),'Request: '+el('method').value];if(el('method').value==='delivery')lines.push('Delivery address: '+el('address').value.trim());if(el('notes').value.trim())lines.push('Notes: '+el('notes').value.trim());lines.push('','Please confirm the current price, availability, and any delivery charge.');const seller=el('seller').value;if(!['2348028091950','2347066052334'].includes(seller))return;window.location.assign('https://wa.me/'+seller+'?text='+encodeURIComponent(lines.join('\n')));};render();
